const emitterFitScratch = {
  kind: 0,
  center: new THREE.Vector3(),
  bx: new THREE.Vector3(),
  by: new THREE.Vector3(),
  bz: new THREE.Vector3(),
  half: new THREE.Vector3(),
  radius: 0,
  reff: 0,
  exHalf: new THREE.Vector3(),
};

